-- Additive internal-only portal operation/conflict workflow. No provider calls.
CREATE TYPE "PortalOperationStatus" AS ENUM ('PENDING', 'RETRYABLE', 'SUCCEEDED', 'DEAD_LETTER');
CREATE TYPE "PortalConflictResolution" AS ENUM ('KEEP_CRM', 'ACCEPT_PORTAL', 'REVIEW');
ALTER TABLE "portal_listings" ADD COLUMN "payloadVersion" INTEGER NOT NULL DEFAULT 1, ADD COLUMN "conflictFields" TEXT, ADD COLUMN "portalSnapshot" TEXT, ADD COLUMN "conflictDetectedAt" TIMESTAMP(3), ADD COLUMN "conflictResolvedAt" TIMESTAMP(3), ADD COLUMN "conflictResolution" "PortalConflictResolution", ADD COLUMN "conflictResolvedById" TEXT;
CREATE TABLE "portal_operations" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL DEFAULT 'org_default', "portalListingId" TEXT, "connectionId" TEXT, "provider" "PropertyPortalProvider" NOT NULL, "operationType" TEXT NOT NULL, "idempotencyKey" TEXT NOT NULL, "status" "PortalOperationStatus" NOT NULL DEFAULT 'PENDING', "failureReason" TEXT, "attemptCount" INTEGER NOT NULL DEFAULT 0, "lastAttemptAt" TIMESTAMP(3), "retryEligibleAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "portal_operations_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "organizations"("id") ON DELETE CASCADE, CONSTRAINT "portal_operations_portalListingId_fkey" FOREIGN KEY ("portalListingId") REFERENCES "portal_listings"("id") ON DELETE SET NULL, CONSTRAINT "portal_operations_connectionId_fkey" FOREIGN KEY ("connectionId") REFERENCES "property_portal_connections"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX "portal_operations_organizationId_idempotencyKey_key" ON "portal_operations"("organizationId", "idempotencyKey");
CREATE INDEX "portal_operations_organizationId_provider_status_retryEligibleAt_idx" ON "portal_operations"("organizationId", "provider", "status", "retryEligibleAt");
